import fs from 'fs';

function exportDeck(filename, varName, deck) {
  const content = `/**
 * DECK: ${deck.title}
 * Giai đoạn ${deck.phase} (${deck.level}) - ${deck.cards.length} từ vựng cốt lõi
 */

export const ${varName} = ${JSON.stringify(deck, null, 2)};
`;
  fs.writeFileSync(`./data/decks/${filename}`, content, 'utf-8');
  console.log(`Saved ./data/decks/${filename} with ${deck.cards.length} cards`);
}

